def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    # Objects are three-cell diamonds (top, shoulder pair, bottom). When two
    # diamonds face one another across a row, color the gap between their inner shoulders.
    diamonds=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c-1]==2 and grid[r][c+1]==2 and grid[r-1][c]==2 and grid[r+1][c]==2:
                diamonds.append((r,c))
    # Horizontal bridge between diamonds with centers on same row, separated by 8.
    for r,c in diamonds:
        for rr,d in diamonds:
            if rr==r and d>c and d-c==8:
                for x in range(c+2,d-1):
                    if grid[r][x]==0: out[r][x]=1
    # Vertical connections between vertically aligned diamonds: color from bottom
    # point of upper to top point of lower (exclusive).
    for r,c in diamonds:
        for rr,d in diamonds:
            if d==c and rr>r and rr-r>=4:
                for y in range(r+2,rr-1):
                    if grid[y][c]==0: out[y][c]=1
    return out
